@main struct PresentationTimingCheck {
 static func check(_ value: Bool, _ message: String) { if !value { fatalError(message) } }
 static func main() {
  check(PresentationTiming.adaptive(platform:"linux", bluetooth:false), "Linux local output learns latency")
  check(PresentationTiming.adaptive(platform:"windows", bluetooth:false), "Windows local output learns latency")
  check(!PresentationTiming.adaptive(platform:"linux", bluetooth:true), "Bluetooth keeps reliable headroom")
  check(!PresentationTiming.adaptive(platform:"macos", bluetooth:false), "Mac without Low latency keeps Reliable")
  check(PresentationTiming.adaptive(platform:"macos", bluetooth:true, lowLatency:true), "Low latency learns Mac Bluetooth timing")
  check(PresentationTiming.adaptive(platform:"macos", bluetooth:false, lowLatency:true), "Low latency learns Mac speaker timing")
  check(PresentationTiming.adaptive(platform:"windows", bluetooth:true, lowLatency:true), "Low latency learns Windows Bluetooth timing")
  check(!PresentationTiming.adaptive(platform:"windows", bluetooth:true, lowLatency:false), "Reliable choice keeps Bluetooth headroom")
  check(PresentationTiming.adaptive(platform:"linux", bluetooth:false, lowLatency:false), "local Linux path always learned")
  check(!PresentationTiming.adaptive(platform:"", bluetooth:false, lowLatency:true), "legacy computer keeps Reliable")
  check(PresentationTiming.floorMs(platform:"linux", bluetooth:false)==40 && PresentationTiming.floorMs(platform:"macos", bluetooth:false)==60 && PresentationTiming.floorMs(platform:"windows", bluetooth:true)==60, "Low latency floors")
  check(PresentationTiming.adaptiveCushion(jitter:3, packet:5, lead:10, floor:60)==60, "floor protects short learning windows")
  check(PresentationTiming.adaptiveCushion(jitter:50, packet:5, lead:10, floor:60)==70, "learned jitter above floor is kept")
  check(PresentationTiming.adaptiveCushion(jitter:900, packet:5, lead:10, floor:60)==320, "Low latency bounded by Reliable cushion")
  check(PresentationTiming.adaptiveCushion(jitter:3, packet:10, lead:20)==43, "stable network reduces buffer")
  check(PresentationTiming.adaptiveCushion(jitter:600, packet:10, lead:20)==320, "jitter bounded to reliable cushion")
  check(PresentationTiming.adaptiveCushion(jitter:0, packet:10, lead:2)==40, "minimum safe local cushion")
  check(PresentationTiming.correctedDelay(20, correction:0)==20, "reset preserves learned interactive prefill")
  check(PresentationTiming.correctedDelay(320, correction:-10)==330, "early sound delayed ten ms")
  check(PresentationTiming.correctedDelay(320, correction:10)==310, "late sound advanced ten ms")
  check(PresentationTiming.correctedDelay(320, correction:500)==40, "bounded network prefill")
  check(PresentationTiming.renderDelay(minimum:320,output:nil,target:0)==320, "solo unchanged before measurement")
  check(PresentationTiming.renderDelay(minimum:320,output:180,target:0)==320, "solo unchanged after measurement")
  check(PresentationTiming.renderDelay(minimum:320,output:20,target:500)+20==500, "speaker group presentation")
  check(PresentationTiming.renderDelay(minimum:320,output:180,target:500)+180==500, "Bluetooth group presentation")
  check(PresentationTiming.renderDelay(minimum:320,output:nil,target:500)==320, "unmeasured output cannot apply target")
  check(PresentationTiming.renderDelay(minimum:320,output:180,target:400)==320, "late join waits for adequate group target")
  check(PresentationTiming.outputDelay(total:500,render:320)==180, "remove render cushion from OS estimate")
  check(PresentationTiming.outputDelay(total:250,render:320)==nil, "reject invalid negative output estimate")
  check(PresentationTiming.renderDelay(minimum:320,output:180,target:0)==320, "last listener leaving restores solo timing")
  check(PresentationTiming.rateCorrection(errorMs:40)==0.001, "late receiver catches up at bounded rate")
  check(PresentationTiming.rateCorrection(errorMs:-40) == -0.001, "early receiver slows at bounded rate")
  check(PresentationTiming.rateCorrection(errorMs:0.5)==0, "sub-millisecond noise does not chase drift")
  print("PASS: presentation timing, Low latency, mixed outputs, late join and solo fallback")
 }
}
